diff --git a/src/retry.ts b/src/retry.ts
+++ b/src/retry.ts
+function step(state) {
+  if (state === 'idle') return 'running';
+  if (state === 'running') {
+    return ok() ? 'done' : 'failed';
+  }
+  if (state === 'failed' && retries < max) {
+    retries++;
+    return 'running';
+  }
+  return state;
+}
